31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email validation: a non-empty local part, a single '@', and a
65	     * domain with at least one dot-separated label ending in a letter-only TLD.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
69	
70	    /** Dedicated audit logger for owner lifecycle side-effects. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    /**
92	     * Normalise a raw telephone number to E.164 form.
93	     *
94	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
95	     * code are kept when present; otherwise country code '+61' is assumed and a
96	     * single leading '0' is dropped from the national digits. The result must have
97	     * between 8 and 15 digits after the '+'.
98	     *
99	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
100	     * national-number length is additionally validated against that country code:
101	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
102	     * length is wrong for its country is rejected.
103	     *
104	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
105	     */
106	    static String toE164(String raw) {
107	        if (raw == null) {
108	            return null;
109	        }
110	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
111	        String digits;
112	        boolean explicitCountryCode;
113	        if (cleaned.startsWith("+")) {
114	            digits = cleaned.substring(1);
115	            explicitCountryCode = true;
116	        } else {
117	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
118	            digits = "61" + national;
119	            explicitCountryCode = false;
120	        }
121	        if (!digits.matches("[0-9]{8,15}")) {
122	            return null;
123	        }
124	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
125	            return null;
126	        }
127	        return "+" + digits;
128	    }
129	
130	    /**
131	     * Validate the national-number length of an E.164 number (its digits without the
132	     * leading '+') against the requirement for its country code: country code '+61'
133	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
134	     * without a configured length requirement are accepted unchanged.
135	     */
136	    private static boolean hasValidNationalLength(String digits) {
137	        if (digits.startsWith("61")) {
138	            return digits.length() - "61".length() == 9;
139	        }
140	        if (digits.startsWith("1")) {
141	            return digits.length() - "1".length() == 10;
142	        }
143	        return true;
144	    }
145	
146	    /**
147	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
148	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
149	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
150	     * input normalises to the empty string.
151	     */
152	    private static String normaliseIdentity(String value) {
153	        if (value == null) {
154	            return "";
155	        }
156	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
157	    }
158	
159	    /**
160	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
161	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
162	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
163	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
164	     * that is both stored and used for every address comparison.
165	     */
166	    static String normaliseAddress(String value) {
167	        if (value == null) {
168	            return "";
169	        }
170	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
171	        if (collapsed.isEmpty()) {
172	            return "";
173	        }
174	        String[] tokens = collapsed.split(" ");
175	        StringBuilder result = new StringBuilder();
176	        for (int i = 0; i < tokens.length; i++) {
177	            if (i > 0) {
178	                result.append(' ');
179	            }
180	            result.append(expandAddressAbbreviation(tokens[i]));
181	        }
182	        return result.toString();
183	    }
184	
185	    /**
186	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
187	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
188	     * returned unchanged.
189	     */
190	    private static String expandAddressAbbreviation(String token) {
191	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
192	        return switch (core) {
193	            case "ST" -> "STREET";
194	            case "RD" -> "ROAD";
195	            case "AVE" -> "AVENUE";
196	            default -> token;
197	        };
198	    }
199	
200	    /**
201	     * Derive the stable, shared household identifier for owners in the same household: the first 12
202	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
203	     * so every owner with the same last name and postcode resolves to the same value regardless of
204	     * the order in which they were created.
205	     */
206	    private static String householdId(String lastNameKey, String postcode) {
207	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
208	    }
209	
210	    /**
211	     * Build an owner's derived duplicate-detection identity key as
212	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
213	     * component contributes the empty string, and the email is lower-cased so the comparison is
214	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
215	     */
216	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
217	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
218	        String emailKey = email == null ? "" : email.toLowerCase();
219	        String household = householdId == null ? "" : householdId;
220	        return telephone + "|" + emailKey + "|" + household;
221	    }
222	
223	    /**
224	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
225	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
226	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
227	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
228	     * only on the owner's own region and identity, not on how many owners already exist.
229	     */
230	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
231	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
232	    }
233	
234	    /**
235	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
236	     */
237	    private static String hash8(String input) {
238	        return hashHex(input, 8, true);
239	    }
240	
241	    /**
242	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
243	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
244	     */
245	    private static String hashHex(String input, int length, boolean upperCase) {
246	        try {
247	            byte[] digest = MessageDigest.getInstance("SHA-256")
248	                .digest(input.getBytes(StandardCharsets.UTF_8));
249	            StringBuilder sb = new StringBuilder(digest.length * 2);
250	            for (byte b : digest) {
251	                sb.append(String.format("%02x", b));
252	            }
253	            String hex = sb.substring(0, length);
254	            return upperCase ? hex.toUpperCase() : hex;
255	        }
256	        catch (java.security.NoSuchAlgorithmException e) {
257	            throw new IllegalStateException(e);
258	        }
259	    }
260	
261	    /**
262	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
263	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
264	     * fixed city-to-region table, else {@code "UNKNOWN"}.
265	     */
266	    private static String region(String postcode, String city) {
267	        String fromPostcode = regionForPostcode(postcode);
268	        return fromPostcode != null ? fromPostcode : regionForCity(city);
269	    }
270	
271	    /**
272	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
273	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
274	     */
275	    private static String regionForPostcode(String postcode) {
276	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
277	            return null;
278	        }
279	        int value = Integer.parseInt(postcode);
280	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
281	            int[] range = entry.getValue();
282	            if (value >= range[0] && value <= range[1]) {
283	                return entry.getKey();
284	            }
285	        }
286	        return null;
287	    }
288	
289	    /**
290	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
291	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
292	     */
293	    static LocalDate toBusinessDay(LocalDate date) {
294	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
295	            date = date.plusDays(1);
296	        }
297	        return date;
298	    }
299	
300	    /**
301	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
302	     * using the same per-day accumulation path as the daily create-limit rule.
303	     */
304	    private long ownersCreatedOn(LocalDate registrationDate) {
305	        LocalDate day = toBusinessDay(registrationDate);
306	        return this.clinicService.findAllOwners().stream()
307	            .map(Owner::getRegistrationDate)
308	            .filter(existing -> existing != null)
309	            .map(OwnerRestControllerV1::toBusinessDay)
310	            .filter(day::equals)
311	            .count();
312	    }
313	
314	    /**
315	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
316	     * postcode against the owner's city region.
317	     */
318	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
319	        "NSW", new int[] {2000, 2099},
320	        "VIC", new int[] {3000, 3099},
321	        "QLD", new int[] {4000, 4099});
322	
323	    /**
324	     * Resolve an owner's region from the city using the fixed city-to-region table
325	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
326	     * when the city is not listed.
327	     */
328	    private static String regionForCity(String city) {
329	        return switch (city == null ? "" : city) {
330	            case "Sydney" -> "NSW";
331	            case "Melbourne" -> "VIC";
332	            case "Brisbane" -> "QLD";
333	            default -> "UNKNOWN";
334	        };
335	    }
336	
337	    /**
338	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
339	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
340	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
341	     */
342	    private static boolean isPostcodeValid(String postcode, String city) {
343	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
344	            return false;
345	        }
346	        int[] range = REGION_POSTCODES.get(regionForCity(city));
347	        if (range == null) {
348	            return true;
349	        }
350	        int value = Integer.parseInt(postcode);
351	        return value >= range[0] && value <= range[1];
352	    }
353	
354	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
355	    @Override
356	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
357	        Collection<Owner> owners;
358	        if (lastName != null) {
359	            owners = this.clinicService.findOwnerByLastName(lastName);
360	        } else {
361	            owners = this.clinicService.findAllOwners();
362	        }
363	        if (owners.isEmpty()) {
364	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
365	        }
366	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
367	    }
368	
369	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
370	    @Override
371	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
372	        Owner owner = this.clinicService.findOwnerById(ownerId);
373	        if (owner == null) {
374	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
375	        }
376	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
377	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
378	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
379	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
380	    }
381	
382	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
383	    @Override
384	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
385	        String telephone = toE164(ownerFieldsDto.getTelephone());
386	        if (telephone == null) {
387	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
388	        }
389	        String email = ownerFieldsDto.getEmail();
390	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
391	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
392	        }
393	        String address = normaliseAddress(ownerFieldsDto.getAddress());
394	        if (address.isEmpty()) {
395	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
396	        }
397	        String postcode = ownerFieldsDto.getPostcode();
398	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
399	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
400	        }
401	        if (ownerFieldsDto.getRegistrationDate() != null
402	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
403	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
404	        }
405	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
406	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
407	        LocalDate registrationDate = toBusinessDay(effectiveDate);
408	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
409	            .map(Owner::getRegistrationDate)
410	            .filter(existing -> existing != null)
411	            .map(OwnerRestControllerV1::toBusinessDay)
412	            .filter(registrationDate::equals)
413	            .count();
414	        if (ownersCreatedThatDay >= 100) {
415	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
416	        }
417	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
418	        long ownersInCity = this.clinicService.findAllOwners().stream()
419	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
420	            .count();
421	        if (ownersInCity >= 50) {
422	            return new ResponseEntity<>(HttpStatus.CONFLICT);
423	        }
424	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
425	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
426	        // The household is deterministically keyed on (normalized last name, postcode): every owner
427	        // with a postcode belongs to the household identified by this computed id, and owners sharing
428	        // a last name and postcode share it automatically.
429	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
430	        // Existing owners already in this household (same last name and postcode).
431	        List<Owner> householdMembers = (householdId == null) ? List.of()
432	            : this.clinicService.findAllOwners().stream()
433	                .filter(existing -> householdId.equals(
434	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
435	                .toList();
436	        // A second owner in an existing household is a household duplicate: rejected with 409 unless
437	        // it declares 'sharesHousehold', which only bypasses this block (the household link itself is
438	        // already assigned deterministically above).
439	        if (!householdMembers.isEmpty() && !sharesHousehold) {
440	            return new ResponseEntity<>(HttpStatus.CONFLICT);
441	        }
442	        String identityKey = identityKey(telephone, email, householdId);
443	        boolean identityInUse = this.clinicService.findAllOwners().stream()
444	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
445	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
446	        if (identityInUse) {
447	            return new ResponseEntity<>(HttpStatus.CONFLICT);
448	        }
449	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
450	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
451	            .filter(existing ->
452	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
453	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
454	            .count();
455	        HttpHeaders headers = new HttpHeaders();
456	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
457	        owner.setNamesakeCount(namesakeCount);
458	        owner.setAddress(address);
459	        owner.setTelephone(telephone);
460	        owner.setEmail(email == null ? null : email.toLowerCase());
461	        owner.setRegistrationDate(registrationDate);
462	        owner.setCustomerCode(nextCustomerCode(
463	            region(postcode, owner.getCity()), telephone, owner.getLastName()));
464	        owner.setHouseholdId(householdId);
465	        // A created owner is never flagged as a suspected duplicate: a lone owner has no household
466	        // peer, and a same-household owner can only be created by declaring 'sharesHousehold', which
467	        // makes it an intentional household member rather than a suspected duplicate.
468	        owner.setPossibleDuplicateOf(null);
469	        this.clinicService.saveOwner(owner);
470	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
471	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
472	            ownerMapper.formatMembershipLevel(owner));
473	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
474	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
475	        headers.setLocation(UriComponentsBuilder.newInstance()
476	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
477	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
478	    }
479	
480	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
481	    @Override
482	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
483	        String telephone = toE164(ownerFieldsDto.getTelephone());
484	        if (telephone == null) {
485	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
486	        }
487	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
488	        if (currentOwner == null) {
489	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
490	        }
491	        String email = ownerFieldsDto.getEmail();
492	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
493	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
494	        }
495	        currentOwner.setAddress(ownerFieldsDto.getAddress());
496	        currentOwner.setCity(ownerFieldsDto.getCity());
497	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
498	        currentOwner.setLastName(ownerFieldsDto.getLastName());
499	        currentOwner.setTelephone(telephone);
500	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
501	        this.clinicService.saveOwner(currentOwner);
502	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
503	    }
504	
505	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
506	    @Transactional
507	    @Override
508	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
509	        Owner owner = this.clinicService.findOwnerById(ownerId);
510	        if (owner == null) {
511	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
512	        }
513	        this.clinicService.deleteOwner(owner);
514	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
515	    }
516	
517	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
518	    @Override
519	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
520	        Owner owner = this.clinicService.findOwnerById(ownerId);
521	        if (owner == null) {
522	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
523	        }
524	        HttpHeaders headers = new HttpHeaders();
525	        Pet pet = petMapper.toPet(petFieldsDto);
526	        owner.setId(ownerId);
527	        pet.setOwner(owner);
528	        pet.getType().setName(null);
529	        this.clinicService.savePet(pet);
530	        PetDto petDto = petMapper.toPetDto(pet);
531	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
532	            .buildAndExpand(pet.getId()).toUri());
533	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
534	    }
535	
536	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
537	    @Override
538	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
539	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
540	        if (currentOwner != null) {
541	            Pet currentPet = this.clinicService.findPetById(petId);
542	            if (currentPet != null) {
543	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
544	                currentPet.setName(petFieldsDto.getName());
545	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
546	                this.clinicService.savePet(currentPet);
547	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
548	            }
549	        }
550	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
551	    }
552	
553	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
554	    @Override
555	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
556	        HttpHeaders headers = new HttpHeaders();
557	        Visit visit = visitMapper.toVisit(visitFieldsDto);
558	        Pet pet = new Pet();
559	        pet.setId(petId);
560	        visit.setPet(pet);
561	        this.clinicService.saveVisit(visit);
562	        VisitDto visitDto = visitMapper.toVisitDto(visit);
563	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
564	            .buildAndExpand(visit.getId()).toUri());
565	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
566	    }
567	
568	
569	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
570	    @Override
571	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
572	        Owner owner = this.clinicService.findOwnerById(ownerId);
573	        if (owner != null) {
574	            Pet pet = owner.getPet(petId);
575	            if (pet != null) {
576	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
577	            }
578	        }
579	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
580	    }
581	}
